import base64
import json


def _encode(timestamp, rec_id):
    raw = json.dumps([timestamp, rec_id]).encode('utf-8')
    return base64.urlsafe_b64encode(raw).decode('ascii')


def _decode(cursor):
    try:
        ts, rec_id = json.loads(base64.urlsafe_b64decode(cursor.encode('ascii')))
    except Exception:
        raise ValueError('invalid cursor')
    return (ts, rec_id)


def page(records, cursor=None, limit=10):
    if not isinstance(limit, int) or limit < 1:
        raise ValueError('limit')
    ordered = sorted(records, key=lambda x: (x['timestamp'], x['id']))
    if cursor is not None:
        c = _decode(cursor)
        ordered = [x for x in ordered if (x['timestamp'], x['id']) > c]
    items = ordered[:limit]
    next_cursor = (
        _encode(items[-1]['timestamp'], items[-1]['id'])
        if len(ordered) > limit
        else None
    )
    return {'items': items, 'next_cursor': next_cursor}
